def fdiff(self, argindex=1):
    from sympy import polygamma
    if argindex == 1:
        # http://functions.wolfram.com/GammaBetaErf/Binomial/20/01/01/
        n, k = self.args
        return binomial(n, k)*(polygamma(0, n + 1) - \
            polygamma(0, n - k + 1))
    elif argindex == 2:
        # http://functions.wolfram.com/GammaBetaErf/Binomial/20/01/02/
        n, k = self.args
        return binomial(n, k)*(polygamma(0, n - k + 1) - \
            polygamma(0, k + 1))
    else:
        raise ArgumentIndexError(self, argindex)

@classmethod
def _eval(self, n, k):
    # n.is_Number and k.is_Integer and k != 1 and n != k
    from sympy.functions.elementary.exponential import log
    from sympy.core import N

    if k.is_Integer:
        if n.is_Integer and n >= 0:
            n, k = int(n), int(k)

            if k > n:
                return S.Zero
            elif k > n // 2:
                k = n - k

            if HAS_GMPY:
                from sympy.core.compatibility import gmpy
                return Integer(gmpy.bincoef(n, k))

            prime_count_estimate = N(n / log(n))

            # if the number of primes less than n is less than k, use prime sieve method
            # otherwise it is more memory efficient to compute factorials explicitly
            if prime_count_estimate < k:
                M, result = int(_sqrt(n)), 1
                for prime in sieve.primerange(2, n + 1):
                    if prime > n - k:
                        result *= prime
                    elif prime > n // 2:
                        continue
                    elif prime > M:
                        if n % prime < k % prime:
                            result *= prime
                    else:
                        N, K = n, k
                        exp = a = 0

                        while N > 0:
                            a = int((N % prime) < (K % prime + a))
                            N, K = N // prime, K // prime
                            exp = a + exp

                        if exp > 0:
                            result *= prime**exp
            else:
                result = ff(n, k) / factorial(k)
            return Integer(result)
        else:
            d = result = n - k + 1
            for i in range(2, k + 1):
                d += 1
                result *= d
                result /= i
            return result

@classmethod
def eval(cls, n, k):
    n, k = map(sympify, (n, k))
    d = n - k
    if d.is_zero or k.is_zero:
        return S.One
    if (k - 1).is_zero:
        return n
    if k.is_integer:
        if k.is_negative:
            return S.Zero
        if n.is_integer and n.is_nonnegative and d.is_negative:
            return S.Zero
        if n.is_number:
            res = cls._eval(n, k)
            return res.expand(basic=True) if res else res
    elif n.is_negative and n.is_integer and not k.is_integer:
        # a special case when binomial evaluates to complex infinity
        return S.ComplexInfinity
    elif k.is_number:
        from sympy import gamma
        return gamma(n + 1)/(gamma(k + 1)*gamma(n - k + 1))


def _eval_expand_func(self, **hints):
    """
    Function to expand binomial(n,k) when m is positive integer
    Also,
    n is self.args[0] and k is self.args[1] while using binomial(n, k)
    """
    n = self.args[0]
    if n.is_Number:
        return binomial(*self.args)

    k = self.args[1]
    if k.is_Add and n in k.args:
        k = n - k

    if k.is_Integer:
        if k == S.Zero:
            return S.One
        elif k < 0:
            return S.Zero
        else:
            n = self.args[0]
            result = n - k + 1
            for i in range(2, k + 1):
                result *= n - k + i
                result /= i
            return result
    else:
        return binomial(*self.args)

def _eval_rewrite_as_factorial(self, n, k):
    return factorial(n)/(factorial(k)*factorial(n - k))

def _eval_rewrite_as_gamma(self, n, k):
    from sympy import gamma
    return gamma(n + 1)/(gamma(k + 1)*gamma(n - k + 1))

def _eval_rewrite_as_tractable(self, n, k):
    return self._eval_rewrite_as_gamma(n, k).rewrite('tractable')

def _eval_rewrite_as_FallingFactorial(self, n, k):
    if k.is_integer:
        return ff(n, k) / factorial(k)

def _eval_is_integer(self):
    n, k = self.args
    if n.is_integer and k.is_integer:
        return True
    elif k.is_integer is False:
        return False

def _eval_is_nonnegative(self):
    if self.args[0].is_integer and self.args[1].is_integer:
        if self.args[0].is_nonnegative and self.args[1].is_nonnegative:
            return True

